import {parse} from './node_modules/.pnpm/yaml@2.9.1/node_modules/yaml/dist/index.js';
import {readFileSync, globSync} from 'node:fs';
const HASH = \"hashFiles('pnpm-lock.yaml', 'vite.config.ts')\";
let bad = 0;
for (const f of globSync('.github/workflows/*.yml').sort()) {
  const d = parse(readFileSync(f,'utf8'));
  for (const [jobName, job] of Object.entries(d.jobs ?? {})) {
    for (const step of job.steps ?? []) {
      const uses = String(step.uses ?? '');
      if (!uses.includes('actions/cache')) continue;
      const key = String(step.with?.key ?? '');
      if (!key.includes('vp-taskcache') && !key.includes('VP_CACHE_KEY_PREFIX')) continue;
      const ok = key.includes(HASH);
      if (!ok) bad++;
      console.log((ok?'ok  ':'BAD ') + f.split('/').pop().padEnd(16) + jobName.padEnd(16) + (uses.includes('/restore')?'restore':'save+restore'));
    }
  }
}
console.log(bad ? '\nFAIL: ' + bad + ' key(s) missing the hash segment' : '\nOK: every vp task-cache key carries the hash segment');
process.exit(bad?1:0);
" 2>&1 | grep -v Debugger", "explanation": "Verify every vp task-cache key across all workflows now contains the hash segment.", "goal": "Verify cache key consistency", "mode": "sync"}

