{"filePath": "/Users/dwahl/Scripts/pantoken/docs/scripts/build-locales.ts", "newString": "/** Run `work` over `items`, keeping at most `limit` in flight. */
export async function runPool<T>(
  items: readonly T[],
  limit: number,
  work: (item: T) => Promise<void>,
): Promise<void> {
  const queue = [...items];
  const workers = Array.from({ length: Math.min(Math.max(limit, 1), queue.length) }, async () => {
    for (let next = queue.shift(); next !== undefined; next = queue.shift()) await work(next);
  });
  await Promise.all(workers);
}

