import {parse} from './node_modules/.pnpm/yaml@2.9.1/node_modules/yaml/dist/index.js';
import {readFileSync} from 'node:fs';
import {execSync} from 'node:child_process';
const paths = parse(readFileSync('.github/workflows/docs.yml','utf8')).on.push.paths;
const toRe = p => new RegExp('^' + p.replace(/[.+^\${}()|[\]\\\\]/g,'\\\\\$&').replace(/\\*\\*/g,'\u0000').replace(/\\*/g,'[^/]*').replace(/\u0000/g,'.*') + '\$');
const rules = paths.map(p => p.startsWith('!') ? {neg:true, re:toRe(p.slice(1))} : {neg:false, re:toRe(p)});
// GitHub semantics: last matching pattern wins per file; a push fires if any file ends up included.
const included = f => { let hit=false; for (const r of rules) if (r.re.test(f)) hit = !r.neg; return hit; };
const check = (label, files) => {
  const matches = files.filter(included);
  console.log(\`\${label.padEnd(34)} triggers=\${matches.length>0}\${matches.length?'  via '+matches.slice(0,2).join(','):''}\`);
};
for (const pr of [188,185,183,181,179,176]) {
